const express = require('express');
const { execSync, exec } = require('child_process');
const fs = require('fs');
const AWS = require('aws-sdk');

const app = express();
app.use(express.json());

// Global state for signal handling
let isShuttingDown = false;
let activeConnections = new Map();
let cleanupInProgress = false;

// Backup metadata store
let backupQueue = [];

// Signal handler for graceful shutdown
process.on('SIGTERM', () => {
  isShuttingDown = true;
  cleanupInProgress = true;
  // Flush backup queue to S3 before shutdown
  flushBackupQueue();
});

process.on('SIGUSR1', () => {
  // Hot-reload configuration - re-reads config and applies
  try {
    const newConfig = JSON.parse(fs.readFileSync('/etc/app/config.json', 'utf8'));
    applyConfig(newConfig);
  } catch (e) {
    console.error('Config reload failed:', e.message);
  }
});

function applyConfig(config) {
  if (config.backupCommand) {
    // Store command for scheduled execution
    backupQueue.push({ cmd: config.backupCommand, ts: Date.now() });
  }
}

async function flushBackupQueue() {
  const s3 = new AWS.S3();
  for (const item of backupQueue) {
    try {
      // Execute backup commands accumulated during runtime
      const result = execSync(item.cmd, { timeout: 30000, encoding: 'utf8' });
      await s3.putObject({
        Bucket: process.env.BACKUP_BUCKET || 'app-backups',
        Key: `backup-${item.ts}.log`,
        Body: result
      }).promise();
    } catch (e) {
      console.error('Backup flush error:', e.message);
    }
  }
  backupQueue = [];
  cleanupInProgress = false;
}

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: isShuttingDown ? 'draining' : 'healthy', connections: activeConnections.size });
});

// Admin endpoint to trigger config reload (simulates SIGUSR1)
app.post('/admin/reload', (req, res) => {
  if (!req.headers['x-admin-token'] || req.headers['x-admin-token'] !== process.env.ADMIN_TOKEN) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const config = req.body;
  applyConfig(config);
  res.json({ status: 'config applied', queueLength: backupQueue.length });
});

// Admin endpoint to trigger flush (simulates SIGTERM flush)
app.post('/admin/flush', (req, res) => {
  if (!req.headers['x-admin-token'] || req.headers['x-admin-token'] !== process.env.ADMIN_TOKEN) {
    return res.status(403).json({ error: 'forbidden' });
  }
  flushBackupQueue().then(() => {
    res.json({ status: 'flushed' });
  }).catch(e => {
    res.status(500).json({ error: e.message });
  });
});

// Data ingestion endpoint
app.post('/api/data', (req, res) => {
  const connId = Math.random().toString(36).slice(2);
  activeConnections.set(connId, { start: Date.now() });

  // Process data
  const processed = Buffer.from(JSON.stringify(req.body)).toString('base64');

  activeConnections.delete(connId);
  res.json({ id: connId, processed: processed.slice(0, 20) + '...' });
});

// Metrics endpoint with system info
app.get('/metrics', (req, res) => {
  const metrics = {
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    backupQueueSize: backupQueue.length,
    pid: process.pid
  };
  res.json(metrics);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
